<?php $err = $_SESSION['_errors'] ?? []; $old = $_SESSION['_old'] ?? []; $v = fn($k) => e($old[$k] ?? ($row[$k] ?? '')); ?>
<div class="panel" style="max-width:640px"><form class="form" method="post" action="<?= e(url('admin/users/simpan')) ?>"><?= Csrf::field() ?><?php if ($row): ?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><?php endif; ?>
<div class="field <?= isset($err['name']) ? 'has-error' : '' ?>"><label>Nama</label><input name="name" required maxlength="100" value="<?= $v('name') ?>"><?php if (isset($err['name'])): ?><small class="field-error"><?= e($err['name']) ?></small><?php endif; ?></div>
<div class="field <?= isset($err['email']) ? 'has-error' : '' ?>"><label>Email</label><input type="email" name="email" required maxlength="150" value="<?= $v('email') ?>"><?php if (isset($err['email'])): ?><small class="field-error"><?= e($err['email']) ?></small><?php endif; ?></div>
<div class="field <?= isset($err['role_id']) ? 'has-error' : '' ?>"><label>Role</label><select name="role_id"><?php foreach ($roles as $r): ?><option value="<?= (int)$r['id'] ?>" <?= (int)($old['role_id'] ?? $row['role_id'] ?? 3) === (int)$r['id'] ? 'selected' : '' ?>><?= e($r['name']) ?></option><?php endforeach; ?></select><?php if (isset($err['role_id'])): ?><small class="field-error"><?= e($err['role_id']) ?></small><?php endif; ?></div>
<div class="field <?= isset($err['password']) ? 'has-error' : '' ?>"><label>Password <?= $row ? '(kosongkan jika tidak diubah)' : '' ?></label><input type="password" name="password" autocomplete="new-password" <?= $row ? '' : 'required' ?>><div class="hint">Minimal 10 karakter, huruf dan angka. User diminta mengganti saat login pertama.</div><?php if (isset($err['password'])): ?><small class="field-error"><?= e($err['password']) ?></small><?php endif; ?></div>
<label class="check"><input type="checkbox" name="is_active" value="1" <?= ($old ? isset($old['is_active']) : (!$row || $row['is_active'])) ? 'checked' : '' ?>> Akun aktif</label><?php if (isset($err['is_active'])): ?><small class="field-error"><?= e($err['is_active']) ?></small><?php endif; ?>
<div class="toolbar"><button class="btn btn-primary" type="submit">Simpan</button><a class="btn btn-outline" href="<?= e(url('admin/users')) ?>">Batal</a></div></form></div><?php clear_old(); ?>
